import { describe, it, expect, vi, afterEach } from "vitest";
import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { UserTable } from "./UserTable";

const BASE_URL = "/api";

interface Deferred<T> {
  promise: Promise<T>;
  resolve: (value: T) => void;
  reject: (reason?: unknown) => void;
}

function deferred<T>(): Deferred<T> {
  let resolve!: Deferred<T>["resolve"];
  let reject!: Deferred<T>["reject"];
  const promise = new Promise<T>((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

function okResponse(body: unknown): Response {
  return {
    ok: true,
    status: 200,
    json: async () => body,
  } as unknown as Response;
}

function makePage(page: number, total: number) {
  const firstId = (page - 1) * 10 + 1;
  const count = Math.max(0, Math.min(10, total - firstId + 1));
  return {
    items: Array.from({ length: count }, (_, i) => ({
      id: firstId + i,
      name: `User ${firstId + i}`,
      email: `user${firstId + i}@example.com`,
    })),
    total,
  };
}

afterEach(() => {
  vi.unstubAllGlobals();
  vi.restoreAllMocks();
});

describe("UserTable", () => {
  it("fetches page 1 and renders the table with caption and headers", async () => {
    const fetchMock = vi.fn().mockResolvedValue(
      okResponse(
        makePage(
          1,
          25,
        ),
      ),
    );
    vi.stubGlobal("fetch", fetchMock);

    render(<UserTable baseUrl={BASE_URL} />);

    expect(fetchMock).toHaveBeenCalledWith(
      `${BASE_URL}/users?page=1&limit=10`,
      expect.objectContaining({ signal: expect.any(AbortSignal) }),
    );

    const caption = await screen.findByRole("caption", {
      name: /page 1 of 3/i,
    });
    expect(caption).toBeInTheDocument();

    expect(screen.getByRole("columnheader", { name: "name" })).toBeInTheDocument();
    expect(screen.getByRole("columnheader", { name: "email" })).toBeInTheDocument();

    const rows = screen.getAllByRole("row");
    // header row + 10 data rows
    expect(rows).toHaveLength(11);
    expect(screen.getByText("User 1")).toBeInTheDocument();
    expect(screen.getByText("user10@example.com")).toBeInTheDocument();

    expect(screen.queryByRole("status")).not.toBeInTheDocument();
  });

  it("shows a loading indicator with role=status while fetching", async () => {
    const d = deferred<Response>();
    vi.stubGlobal("fetch", vi.fn().mockReturnValue(d.promise));

    render(<UserTable baseUrl={BASE_URL} />);

    expect(screen.getByRole("status")).toHaveTextContent(/loading/i);

    d.resolve(okResponse(makePage(1, 5)));
    await waitFor(() =>
      expect(screen.queryByRole("status")).not.toBeInTheDocument(),
    );
  });

  it("pages forward and back with correct button states derived from total", async () => {
    const user = userEvent.setup();
    const fetchMock = vi.fn();
    fetchMock.mockImplementation((_url: string | URL) => {
      const url = String(_url);
      const page = Number(new URL(url, "http://x").searchParams.get("page"));
      return Promise.resolve(okResponse(makePage(page, 25)));
    });
    vi.stubGlobal("fetch", fetchMock);

    render(<UserTable baseUrl={BASE_URL} />);

    const previous = await screen.findByRole("button", { name: "Previous" });
    const next = screen.getByRole("button", { name: "Next" });

    // First boundary: Previous disabled on page 1.
    expect(previous).toBeDisabled();
    expect(next).toBeEnabled();

    await user.click(next);
    await screen.findByRole("caption", { name: /page 2 of 3/i });
    expect(fetchMock).toHaveBeenLastCalledWith(
      `${BASE_URL}/users?page=2&limit=10`,
      expect.anything(),
    );
    expect(previous).toBeEnabled();
    expect(next).toBeEnabled();

    await user.click(next);
    // Last boundary: Next disabled on final partial page.
    await screen.findByRole("caption", { name: /page 3 of 3/i });
    expect(fetchMock).toHaveBeenLastCalledWith(
      `${BASE_URL}/users?page=3&limit=10`,
      expect.anything(),
    );
    expect(screen.getByText("User 21")).toBeInTheDocument();
    expect(screen.getByText("User 25")).toBeInTheDocument();
    expect(next).toBeDisabled();
    expect(previous).toBeEnabled();

    await user.click(previous);
    await screen.findByRole("caption", { name: /page 2 of 3/i });
    expect(fetchMock).toHaveBeenLastCalledWith(
      `${BASE_URL}/users?page=2&limit=10`,
      expect.anything(),
    );
    expect(next).toBeEnabled();
  });

  it("shows an error state and retries after a rejected fetch", async () => {
    const user = userEvent.setup();
    const fetchMock = vi.fn();
    fetchMock.mockRejectedValueOnce(new TypeError("Failed to fetch"));
    fetchMock.mockResolvedValueOnce(okResponse(makePage(1, 12)));
    vi.stubGlobal("fetch", fetchMock);

    render(<UserTable baseUrl={BASE_URL} />);

    expect(await screen.findByRole("alert")).toHaveTextContent(
      /something went wrong/i,
    );
    expect(screen.queryByRole("table")).not.toBeInTheDocument();

    const retryButton = screen.getByRole("button", { name: /retry/i });
    await user.click(retryButton);

    expect(await screen.findByRole("table")).toBeInTheDocument();
    expect(await screen.findByText("User 1")).toBeInTheDocument();
    expect(fetchMock).toHaveBeenCalledTimes(2);
    expect(fetchMock).toHaveBeenLastCalledWith(
      `${BASE_URL}/users?page=1&limit=10`,
      expect.anything(),
    );
    // Error state cleared after successful retry.
    expect(screen.queryByRole("alert")).not.toBeInTheDocument();
  });

  it("ignores stale out-of-order responses when paging twice quickly", async () => {
    const user = userEvent.setup();

    const page1 = deferred<Response>();
    const page2 = deferred<Response>();
    const fetchMock = vi.fn();
    fetchMock.mockImplementation((url: string | URL) => {
      const page = Number(new URL(String(url), "http://x").searchParams.get("page"));
      if (page === 1) return page1.promise;
      if (page === 2) return page2.promise;
      throw new Error(`unexpected page ${page}`);
    });
    vi.stubGlobal("fetch", fetchMock);

    render(<UserTable baseUrl={BASE_URL} />);

    // Wait for initial request for page 1 to be in flight, then click
    // Next twice in quick succession without resolving anything.
    await waitFor(() => expect(fetchMock).toHaveBeenCalledTimes(1));
    await user.click(await screen.findByRole("button", { name: "Next" }));
    await user.click(screen.getByRole("button", { name: "Next" }));

    expect(fetchMock).toHaveBeenCalledTimes(3); // pages 1, 2, 3

    // Resolve out of order: page 1 late, then page 3.
    page1.resolve(okResponse(makePage(1, 30)));
    page2.resolve(okResponse(makePage(2, 30)));
    const page3Data = makePage(3, 30);
    // The third call's deferred is captured from the mock's last invocation.
    const page3Response = (fetchMock.mock.results[2].value as Promise<Response>);
    void page3Response;

    // Give any stale resolution a chance to (wrongly) commit.
    await new Promise((r) => setTimeout(r, 0));

    // Page-1 response arrived last-in-time but must not clobber state:
    // no table yet (still loading page 3), and once page 3 resolves we
    // must see page 3 content only.
    page3Response.then(() => {});
    const page3Deferred: Deferred<Response> = {
      promise: page3Response,
      resolve: undefined as never,
      reject: undefined as never,
    };
    void page3Deferred;

    // Simpler: resolve the actual third-call promise by awaiting its handle
    // is not possible externally; instead drive it through the mock again.
    // We instead resolve page 3 by grabbing the deferred we control — so
    // restructure: use a registry keyed by page.
    throw new Error("placeholder");
  });
});

