import { describe, it, expect, vi, afterEach } from "vitest";
import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { UserTable } from "./UserTable";

const BASE_URL = "/api";

interface Deferred<T> {
  promise: Promise<T>;
  resolve: (value: T) => void;
  reject: (reason?: unknown) => void;
}

function deferred<T>(): Deferred<T> {
  let resolve!: Deferred<T>["resolve"];
  let reject!: Deferred<T>["reject"];
  const promise = new Promise<T>((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

function okResponse(body: unknown): Response {
  return {
    ok: true,
    status: 200,
    json: async () => body,
  } as unknown as Response;
}

/** {items, total} payload where item i has id/name/email User i. */
function makePage(page: number, total: number) {
  const firstId = (page - 1) * 10 + 1;
  const count = Math.max(0, Math.min(10, total - firstId + 1));
  return {
    items: Array.from({ length: count }, (_, i) => ({
      id: firstId + i,
      name: `User ${firstId + i}`,
      email: `user${firstId + i}@example.com`,
    })),
    total,
  };
}

function pageOf(callArg: string | URL): number {
  return Number(
    new URL(String(callArg), "http://localhost").searchParams.get("page"),
  );
}

afterEach(() => {
  vi.unstubAllGlobals();
  vi.restoreAllMocks();
});

describe("UserTable", () => {
  it("fetches page 1 and renders table, caption, headers and rows", async () => {
    const fetchMock = vi.fn().mockResolvedValue(okResponse(makePage(1, 25)));
    vi.stubGlobal("fetch", fetchMock);

    render(<UserTable baseUrl={BASE_URL} />);

    expect(fetchMock).toHaveBeenCalledWith(
      `${BASE_URL}/users?page=1&limit=10`,
      expect.anything(),
    );

    const table = await screen.findByRole("table");
    expect(table).toBeInTheDocument();
    expect(screen.getByText(/page 1 of 3/i)).toBeInTheDocument();

    expect(
      screen.getByRole("columnheader", { name: "name" }),
    ).toBeInTheDocument();
    expect(
      screen.getByRole("columnheader", { name: "email" }),
    ).toBeInTheDocument();

    // header row + 10 data rows
    expect(screen.getAllByRole("row")).toHaveLength(11);
    expect(screen.getByText("User 1")).toBeInTheDocument();
    expect(screen.getByText("user10@example.com")).toBeInTheDocument();

    // Loading indicator gone once data arrived.
    expect(screen.queryByRole("status")).not.toBeInTheDocument();
  });

  it("shows a visible loading indicator with role=status while fetching", async () => {
    const d = deferred<Response>();
    const fetchMock = vi.fn().mockReturnValue(d.promise);
    vi.stubGlobal("fetch", fetchMock);

    render(<UserTable baseUrl={BASE_URL} />);

    expect(screen.getByRole("status")).toHaveTextContent(/loading/i);
    expect(screen.queryByRole("table")).not.toBeInTheDocument();

    d.resolve(okResponse(makePage(1, 5)));
    await waitFor(() =>
      expect(screen.queryByRole("status")).not.toBeInTheDocument(),
    );
  });

  it("pages back and forth with disabled boundaries derived from total", async () => {
    const user = userEvent.setup();
    const fetchMock = vi.fn(async (url: string | URL) =>
      okResponse(makePage(pageOf(url), 25)),
    );
    vi.stubGlobal("fetch", fetchMock);

    render(<UserTable baseUrl={BASE_URL} />);

    const previous = await screen.findByRole("button", { name: "Previous" });
    const next = screen.getByRole("button", { name: "Next" });

    // First boundary.
    expect(previous).toBeDisabled();
    expect(next).toBeEnabled();

    await user.click(next);
    await screen.findByText(/page 2 of 3/i);
    expect(fetchMock).toHaveBeenLastCalledWith(
      `${BASE_URL}/users?page=2&limit=10`,
      expect.anything(),
    );
    expect(previous).toBeEnabled();
    expect(next).toBeEnabled();

    // Last (partial) boundary: users 21–25 of 25.
    await user.click(next);
    await screen.findByText(/page 3 of 3/i);
    expect(fetchMock).toHaveBeenLastCalledWith(
      `${BASE_URL}/users?page=3&limit=10`,
      expect.anything(),
    );
    expect(screen.getByText("User 21")).toBeInTheDocument();
    expect(screen.getByText("User 25")).toBeInTheDocument();
    expect(screen.queryByText("User 26")).not.toBeInTheDocument();
    expect(next).toBeDisabled();
    expect(previous).toBeEnabled();

    await user.click(previous);
    await screen.findByText(/page 2 of 3/i);
    expect(fetchMock).toHaveBeenLastCalledWith(
      `${BASE_URL}/users?page=2&limit=10`,
      expect.anything(),
    );
    expect(previous).toBeEnabled();
    expect(next).toBeEnabled();
  });

  it("shows an error state with Retry and recovers after a rejected fetch", async () => {
    const user = userEvent.setup();
    const fetchMock = vi.fn();
    fetchMock.mockRejectedValueOnce(new TypeError("Failed to fetch"));
    fetchMock.mockResolvedValueOnce(okResponse(makePage(1, 12)));
    vi.stubGlobal("fetch", fetchMock);

    render(<UserTable baseUrl={BASE_URL} />);

    expect(await screen.findByRole("alert")).toHaveTextContent(
      /something went wrong/i,
    );
    expect(screen.queryByRole("table")).not.toBeInTheDocument();

    await user.click(screen.getByRole("button", { name: /retry/i }));

    const table = await screen.findByRole("table");
    expect(table).toBeInTheDocument();
    expect(screen.getByText("User 1")).toBeInTheDocument();
    expect(screen.queryByRole("alert")).not.toBeInTheDocument();

    expect(fetchMock).toHaveBeenCalledTimes(2);
    expect(fetchMock).toHaveBeenLastCalledWith(
      `${BASE_URL}/users?page=1&limit=10`,
      expect.anything(),
    );
  });

  it("ignores stale out-of-order responses when paging forward twice quickly", async () => {
    const user = userEvent.setup();

    // One deferred per requested page, keyed by page number.
    const deferreds = new Map<number, Deferred<Response>>();
    const fetchMock = vi.fn((url: string | URL) => {
      const d = deferred<Response>();
      deferreds.set(pageOf(url), d);
      return d.promise;
    });
    vi.stubGlobal("fetch", fetchMock);

    render(<UserTable baseUrl={BASE_URL} />);

    // Initial load resolves normally so page 1 is displayed.
    deferreds.get(1)!.resolve(okResponse(makePage(1, 30)));
    await screen.findByText(/page 1 of 3/i);

    // Page forward twice quickly: requests for pages 2 and 3 are now
    // in flight simultaneously, neither answered yet.
    await user.click(screen.getByRole("button", { name: "Next" }));
    await user.click(screen.getByRole("button", { name: "Next" }));
    expect(fetchMock).toHaveBeenCalledTimes(3);
    expect(deferreds.has(2)).toBe(true);
    expect(deferreds.has(3)).toBe(true);

    // Resolve in reverse order: page 3 lands first...
    deferreds.get(3)!.resolve(okResponse(makePage(3, 30)));
    await screen.findByText(/page 3 of 3/i);
    expect(screen.getByText("User 21")).toBeInTheDocument();

    // ...and the late-arriving page-2 response must NOT clobber page 3.
    deferreds.get(2)!.resolve(okResponse(makePage(2, 30)));
    await new Promise((r) => setTimeout(r, 25));

    expect(screen.getByText(/page 3 of 3/i)).toBeInTheDocument();
    expect(screen.getByText("User 21")).toBeInTheDocument();
    expect(screen.queryByText("User 11")).not.toBeInTheDocument();
  });
});

