import { useCallback, useEffect, useRef, useState } from "react";

export interface User {
  id: number;
  name: string;
  email: string;
}

interface UsersResponse {
  items: User[];
  total: number;
}

const PAGE_SIZE = 10;

interface UserTableProps {
  baseUrl: string;
}

export function UserTable({ baseUrl }: UserTableProps) {
  const [page, setPage] = useState(1);
  const [items, setItems] = useState<User[] | null>(null);
  // Last known total; kept across loads so button disabled states remain
  // stable while a new page is in flight.
  const [total, setTotal] = useState<number | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);
  const [reloadToken, setReloadToken] = useState(0);

  // Guards against stale responses: each fetch gets an id, and only the
  // latest one may commit state. AbortController is belt-and-braces on top.
  const requestIdRef = useRef(0);

  useEffect(() => {
    const requestId = ++requestIdRef.current;
    const controller = new AbortController();
    setLoading(true);
    setError(false);

    async function load() {
      try {
        const res = await fetch(
          `${baseUrl}/users?page=${page}&limit=${PAGE_SIZE}`,
          { signal: controller.signal },
        );
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = (await res.json()) as UsersResponse;
        if (requestId !== requestIdRef.current) return; // stale
        setItems(data.items);
        setTotal(data.total);
        setLoading(false);
      } catch (err) {
        if (controller.signal.aborted) return; // superseded, not an error
        if (requestId !== requestIdRef.current) return; // stale
        setError(true);
        setLoading(false);
      }
    }

    void load();
    return () => controller.abort();
  }, [baseUrl, page, reloadToken]);

  const retry = useCallback(() => {
    setReloadToken((t) => t + 1);
  }, []);

  const maxPage =
    total === null ? null : Math.max(1, Math.ceil(total / PAGE_SIZE));

  return (
    <section aria-label="Users">
      {items !== null && !error && (
        <table>
          <caption>
            Users (page {page} of {maxPage})
          </caption>
          <thead>
            <tr>
              <th scope="col">name</th>
              <th scope="col">email</th>
            </tr>
          </thead>
          <tbody>
            {items.map((user) => (
              <tr key={user.id}>
                <td>{user.name}</td>
                <td>{user.email}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {loading && <p role="status">Loading users…</p>}

      {error && (
        <div>
          <p role="alert">Something went wrong while loading users.</p>
          <button type="button" onClick={retry}>
            Retry
          </button>
        </div>
      )}

      <div>
        {/* Disabled states are derived solely from the boundaries:
            page 1 and the final page implied by total. */}
        <button
          type="button"
          onClick={() => setPage((p) => Math.max(1, p - 1))}
          disabled={page <= 1}
        >
          Previous
        </button>{" "}
        <button
          type="button"
          onClick={() => setPage((p) => p + 1)}
          disabled={maxPage === null || page >= maxPage}
        >
          Next
        </button>
      </div>
    </section>
  );
}

export default UserTable;

